#include <stdint.h>

#define RCC_AHBENR (*(volatile uint32_t *)0x40021014u)
#define GPIOA_MODER (*(volatile uint32_t *)0x48000000u)
#define GPIOA_BSRR (*(volatile uint32_t *)0x48000018u)

#define LED_PWM_PIN 1u
#define LED_PWM_SET (1u << LED_PWM_PIN)
#define LED_PWM_RESET (1u << (LED_PWM_PIN + 16u))

static void delay(volatile uint32_t count)
{
    while (count > 0u)
    {
        --count;
    }
}

int main(void)
{
    RCC_AHBENR |= (1u << 17); /* Enable GPIOA clock. */

    GPIOA_BSRR = LED_PWM_RESET;
    GPIOA_MODER = (GPIOA_MODER & ~(3u << (LED_PWM_PIN * 2u))) |
                  (1u << (LED_PWM_PIN * 2u));

    for (;;)
    {
        GPIOA_BSRR = LED_PWM_SET;
        delay(1000000u);

        GPIOA_BSRR = LED_PWM_RESET;
        delay(1000000u);
    }
}
